class Solution:
    def minOperations(self, nums: List[int], k: int) -> int:
        cnt = 0
        i = len(nums) - 1

        while i >= 0:
            if i < k:
                if nums[i] > 0:
                    cnt += 1
                    nums[i] *= -1
                    if cnt == k:
                        return len(nums) - i
                else:
                    break
            else:
                break
            i -= 1

        return len(nums) - i
